-- ZettaPlanner initial schema. CONTRACT.md §6.1.
--
-- Conventions: snake_case, TIMESTAMPTZ, UUIDv7 primary keys generated by the
-- application (sortable, index-friendly). Large text stays in the database;
-- uploaded images go to disk and are referenced by path.
--
-- Two things in here are not in the contract's SQL block and are not optional:
-- the deleted_at columns required by §6.5 constraint 1, and the append-only
-- enforcement on audit_log. Both are listed in the contract's prose.

-- pgvector is asserted, not created. Creating an extension requires superuser,
-- and a migration runner that needs superuser is a deployment where the
-- application role has it — which is a far larger problem than a manual setup
-- step. So: name the fix and stop.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'vector') THEN
    RAISE EXCEPTION
      'the pgvector extension is not installed in this database. Install the package (on Debian/Ubuntu: postgresql-18-pgvector) and then, as a superuser: CREATE EXTENSION vector;'
      USING ERRCODE = 'feature_not_supported';
  END IF;
END $$;

-- ── identity ─────────────────────────────────────────────────────────────────

CREATE TABLE users (
  id            UUID PRIMARY KEY,
  email         TEXT UNIQUE NOT NULL,
  display_name  TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL CHECK (role IN ('admin', 'manager', 'developer')),
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  created_at    TIMESTAMPTZ NOT NULL,
  updated_at    TIMESTAMPTZ NOT NULL,
  deleted_at    TIMESTAMPTZ
);

-- Agents get an actor row at creation, not on first use, so an audit row can
-- never reference a principal that does not exist.
CREATE TABLE actors (
  id         UUID PRIMARY KEY,
  kind       TEXT NOT NULL CHECK (kind IN ('human', 'agent', 'system')),
  user_id    UUID REFERENCES users(id),
  agent_name TEXT,
  model_ref  TEXT,
  created_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT actor_human_has_user CHECK (kind <> 'human' OR user_id IS NOT NULL),
  CONSTRAINT actor_agent_has_name CHECK (kind <> 'agent' OR agent_name IS NOT NULL)
);
CREATE UNIQUE INDEX actors_user_unique ON actors (user_id) WHERE kind = 'human';

CREATE TABLE projects (
  id          UUID PRIMARY KEY,
  key         TEXT UNIQUE NOT NULL,
  name        TEXT NOT NULL,
  description TEXT,
  status      TEXT NOT NULL,
  settings    JSONB NOT NULL DEFAULT '{}',
  git_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL,
  deleted_at  TIMESTAMPTZ
);

CREATE TABLE project_members (
  project_id UUID NOT NULL REFERENCES projects(id),
  user_id    UUID NOT NULL REFERENCES users(id),
  role       TEXT NOT NULL CHECK (role IN ('admin', 'manager', 'developer')),
  PRIMARY KEY (project_id, user_id)
);

-- ── diagram: semantic ────────────────────────────────────────────────────────

-- The closed vocabulary (D6, §3.3) is a database constraint as well as an
-- application check. The contract says vocabulary changes are a schema
-- migration plus a prompt version bump; this is what makes that literally true
-- rather than a convention. The teaching error text lives in the service layer;
-- these constraints exist so a bug there cannot widen the vocabulary.
CREATE TABLE catalog_entities (
  id         UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id),
  kind       TEXT NOT NULL CHECK (kind IN (
               'system', 'service', 'component', 'datastore', 'queue',
               'external_system', 'actor', 'api', 'job', 'boundary', 'note')),
  name       TEXT NOT NULL,
  slug       TEXT NOT NULL,
  summary    TEXT,
  attrs      JSONB NOT NULL DEFAULT '{}',
  provenance TEXT NOT NULL CHECK (provenance IN (
               'vlm_extracted', 'human_created', 'human_edited',
               'agent_proposed', 'agent_committed', 'system')),
  actor_id   UUID NOT NULL REFERENCES actors(id),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  deleted_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX catalog_entities_slug ON catalog_entities (project_id, slug)
  WHERE deleted_at IS NULL;
CREATE INDEX catalog_entities_project ON catalog_entities (project_id, kind);

CREATE TABLE diagrams (
  id               UUID PRIMARY KEY,
  project_id       UUID NOT NULL REFERENCES projects(id),
  name             TEXT NOT NULL,
  level            TEXT NOT NULL CHECK (level IN ('context', 'container', 'component')),
  -- Flips to 'manual' on the first coordinate write and does not flip back
  -- without an explicit destructive confirm (§3.2).
  layout_mode      TEXT NOT NULL DEFAULT 'auto' CHECK (layout_mode IN ('auto', 'manual')),
  current_revision INT NOT NULL DEFAULT 0,
  created_at       TIMESTAMPTZ NOT NULL,
  updated_at       TIMESTAMPTZ NOT NULL,
  deleted_at       TIMESTAMPTZ
);
CREATE INDEX diagrams_project ON diagrams (project_id);

CREATE TABLE diagram_nodes (
  id              UUID PRIMARY KEY,
  diagram_id      UUID NOT NULL REFERENCES diagrams(id),
  entity_id       UUID NOT NULL REFERENCES catalog_entities(id),
  label_override  TEXT,
  attrs           JSONB NOT NULL DEFAULT '{}',
  parent_node_id  UUID REFERENCES diagram_nodes(id),
  provenance      TEXT NOT NULL CHECK (provenance IN (
                    'vlm_extracted', 'human_created', 'human_edited',
                    'agent_proposed', 'agent_committed', 'system')),
  -- Low confidence is a first-class value, not a guess. An element the vision
  -- model could not read is stored with low confidence and surfaced for review;
  -- it is never given an invented label (BACKEND.md Phase 3).
  confidence      REAL CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  actor_id        UUID NOT NULL REFERENCES actors(id),
  origin_revision INT NOT NULL,
  deleted_at      TIMESTAMPTZ
);
CREATE UNIQUE INDEX diagram_nodes_placement ON diagram_nodes (diagram_id, entity_id)
  WHERE deleted_at IS NULL;
CREATE INDEX diagram_nodes_entity ON diagram_nodes (entity_id) WHERE deleted_at IS NULL;
CREATE INDEX diagram_nodes_parent ON diagram_nodes (parent_node_id) WHERE parent_node_id IS NOT NULL;

CREATE TABLE diagram_edges (
  id              UUID PRIMARY KEY,
  diagram_id      UUID NOT NULL REFERENCES diagrams(id),
  from_node_id    UUID NOT NULL REFERENCES diagram_nodes(id),
  to_node_id      UUID NOT NULL REFERENCES diagram_nodes(id),
  relation        TEXT NOT NULL CHECK (relation IN (
                    'calls', 'depends_on', 'reads_from', 'writes_to',
                    'publishes_to', 'subscribes_to', 'contains', 'deploys_to',
                    'data_flow')),
  label           TEXT,
  attrs           JSONB NOT NULL DEFAULT '{}',
  provenance      TEXT NOT NULL CHECK (provenance IN (
                    'vlm_extracted', 'human_created', 'human_edited',
                    'agent_proposed', 'agent_committed', 'system')),
  confidence      REAL CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  actor_id        UUID NOT NULL REFERENCES actors(id),
  origin_revision INT NOT NULL,
  deleted_at      TIMESTAMPTZ
);
CREATE UNIQUE INDEX diagram_edges_unique
  ON diagram_edges (diagram_id, from_node_id, to_node_id, relation)
  WHERE deleted_at IS NULL;
CREATE INDEX diagram_edges_from ON diagram_edges (from_node_id) WHERE deleted_at IS NULL;
CREATE INDEX diagram_edges_to   ON diagram_edges (to_node_id)   WHERE deleted_at IS NULL;

-- ── diagram: presentation ────────────────────────────────────────────────────
-- Never read by the serializer or by context assembly (D5). The separation is
-- enforced structurally by an import test, not by filtering at the call site.

CREATE TABLE diagram_layout (
  diagram_id UUID NOT NULL REFERENCES diagrams(id),
  node_id    UUID NOT NULL REFERENCES diagram_nodes(id),
  x          DOUBLE PRECISION,
  y          DOUBLE PRECISION,
  w          DOUBLE PRECISION,
  h          DOUBLE PRECISION,
  collapsed  BOOLEAN NOT NULL DEFAULT FALSE,
  -- Set when a node arrives on a manual diagram without coordinates. Cleared on
  -- the first human move (§3.2).
  unplaced   BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (diagram_id, node_id)
);

CREATE TABLE diagram_edge_layout (
  diagram_id UUID NOT NULL REFERENCES diagrams(id),
  edge_id    UUID NOT NULL REFERENCES diagram_edges(id),
  waypoints  JSONB NOT NULL DEFAULT '[]',
  PRIMARY KEY (diagram_id, edge_id)
);

CREATE TABLE diagram_revisions (
  id         UUID PRIMARY KEY,
  diagram_id UUID NOT NULL REFERENCES diagrams(id),
  seq        INT NOT NULL,
  actor_id   UUID NOT NULL REFERENCES actors(id),
  summary    TEXT,
  changes    JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (diagram_id, seq)
);

-- Leases, not locks or CRDTs (D9). One row per diagram; expiry is checked on
-- read, so a crashed holder cannot block a diagram indefinitely.
CREATE TABLE diagram_leases (
  diagram_id    UUID PRIMARY KEY REFERENCES diagrams(id),
  actor_id      UUID NOT NULL REFERENCES actors(id),
  base_revision INT NOT NULL,
  acquired_at   TIMESTAMPTZ NOT NULL,
  heartbeat_at  TIMESTAMPTZ NOT NULL,
  expires_at    TIMESTAMPTZ NOT NULL
);

-- ── ingest ───────────────────────────────────────────────────────────────────

CREATE TABLE ingests (
  id           UUID PRIMARY KEY,
  project_id   UUID NOT NULL REFERENCES projects(id),
  status       TEXT NOT NULL CHECK (status IN (
                 'uploaded', 'extracting', 'merging', 'review', 'accepted', 'failed')),
  source_kind  TEXT NOT NULL CHECK (source_kind IN ('image', 'pdf')),
  diagram_id   UUID REFERENCES diagrams(id),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  error_class  TEXT,
  error_detail TEXT,
  created_at   TIMESTAMPTZ NOT NULL,
  updated_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX ingests_project ON ingests (project_id, created_at DESC);

-- extracted holds the raw per-page model output, kept forever. When extraction
-- is wrong you will want the input, and re-running costs tokens and is not
-- reproducible (BACKEND.md Phase 3).
CREATE TABLE ingest_pages (
  id          UUID PRIMARY KEY,
  ingest_id   UUID NOT NULL REFERENCES ingests(id),
  page_idx    INT NOT NULL,
  image_path  TEXT NOT NULL,
  status      TEXT NOT NULL,
  extracted   JSONB,
  model       TEXT,
  tokens_in   INT,
  tokens_out  INT,
  error_class TEXT,
  UNIQUE (ingest_id, page_idx)
);

-- ── plan ─────────────────────────────────────────────────────────────────────

CREATE TABLE milestones (
  id         UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id),
  name       TEXT NOT NULL,
  intent     TEXT,
  seq        INT NOT NULL,
  start_date DATE,
  due_date   DATE,
  status     TEXT NOT NULL,
  provenance TEXT NOT NULL CHECK (provenance IN (
               'vlm_extracted', 'human_created', 'human_edited',
               'agent_proposed', 'agent_committed', 'system')),
  actor_id   UUID NOT NULL REFERENCES actors(id),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  deleted_at TIMESTAMPTZ
);
CREATE INDEX milestones_project ON milestones (project_id, seq) WHERE deleted_at IS NULL;

CREATE TABLE work_items (
  id                  UUID PRIMARY KEY,
  project_id          UUID NOT NULL REFERENCES projects(id),
  milestone_id        UUID REFERENCES milestones(id),
  ref                 TEXT NOT NULL,
  title               TEXT NOT NULL,
  intent              TEXT,
  acceptance_criteria TEXT,
  status              TEXT NOT NULL CHECK (status IN (
                        'todo', 'in_progress', 'blocked', 'review', 'done', 'dropped')),
  progress_pct        INT NOT NULL DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100),
  priority            TEXT,
  assignee_id         UUID REFERENCES users(id),
  start_date          DATE,
  due_date            DATE,
  provenance          TEXT NOT NULL CHECK (provenance IN (
                        'vlm_extracted', 'human_created', 'human_edited',
                        'agent_proposed', 'agent_committed', 'system')),
  actor_id            UUID NOT NULL REFERENCES actors(id),
  created_at          TIMESTAMPTZ NOT NULL,
  updated_at          TIMESTAMPTZ NOT NULL,
  deleted_at          TIMESTAMPTZ,
  -- Not a partial unique index: a human-facing ref is permanent. ZP-14 must
  -- never be reissued after ZP-14 is dropped, because the audit log and every
  -- worklog referring to it would then be ambiguous.
  UNIQUE (project_id, ref)
);
CREATE INDEX work_items_project_status ON work_items (project_id, status) WHERE deleted_at IS NULL;
CREATE INDEX work_items_assignee ON work_items (assignee_id, status) WHERE deleted_at IS NULL;
CREATE INDEX work_items_milestone ON work_items (milestone_id) WHERE deleted_at IS NULL;

CREATE TABLE sub_tasks (
  id           UUID PRIMARY KEY,
  work_item_id UUID NOT NULL REFERENCES work_items(id),
  title        TEXT NOT NULL,
  status       TEXT NOT NULL,
  seq          INT NOT NULL,
  assignee_id  UUID REFERENCES users(id),
  provenance   TEXT NOT NULL CHECK (provenance IN (
                 'vlm_extracted', 'human_created', 'human_edited',
                 'agent_proposed', 'agent_committed', 'system')),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  created_at   TIMESTAMPTZ NOT NULL,
  updated_at   TIMESTAMPTZ NOT NULL,
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX sub_tasks_item ON sub_tasks (work_item_id, seq) WHERE deleted_at IS NULL;

-- Cycles in 'blocks' are rejected at write time by a depth-limited recursive
-- CTE (BACKEND.md Phase 4). A cycle that lands here is found later by an agent
-- that traverses it forever.
CREATE TABLE item_dependencies (
  from_item_id UUID NOT NULL REFERENCES work_items(id),
  to_item_id   UUID NOT NULL REFERENCES work_items(id),
  kind         TEXT NOT NULL CHECK (kind IN ('blocks', 'relates')),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  created_at   TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (from_item_id, to_item_id, kind),
  CONSTRAINT item_dependency_not_self CHECK (from_item_id <> to_item_id)
);
CREATE INDEX item_dependencies_to ON item_dependencies (to_item_id, kind);

-- Set explicitly by a human or an agent, never derived (§3.5).
CREATE TABLE item_entity_refs (
  work_item_id UUID NOT NULL REFERENCES work_items(id),
  entity_id    UUID NOT NULL REFERENCES catalog_entities(id),
  relation     TEXT NOT NULL DEFAULT 'implements',
  actor_id     UUID NOT NULL REFERENCES actors(id),
  PRIMARY KEY (work_item_id, entity_id, relation)
);
CREATE INDEX item_entity_refs_entity ON item_entity_refs (entity_id);

CREATE TABLE checklist_items (
  id           UUID PRIMARY KEY,
  work_item_id UUID NOT NULL REFERENCES work_items(id),
  text         TEXT NOT NULL,
  checked      BOOLEAN NOT NULL DEFAULT FALSE,
  checked_by   UUID REFERENCES actors(id),
  checked_at   TIMESTAMPTZ,
  seq          INT NOT NULL,
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX checklist_items_item ON checklist_items (work_item_id, seq) WHERE deleted_at IS NULL;

-- Never deleted at all; correct by adding (§6.5 constraint 1). Enforced below.
CREATE TABLE worklogs (
  id           UUID PRIMARY KEY,
  project_id   UUID NOT NULL REFERENCES projects(id),
  work_item_id UUID REFERENCES work_items(id),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  kind         TEXT NOT NULL CHECK (kind IN ('progress', 'deviation', 'note')),
  body         TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX worklogs_project_at ON worklogs (project_id, created_at DESC);
CREATE INDEX worklogs_item_at ON worklogs (work_item_id, created_at DESC);

CREATE TABLE deviations (
  id           UUID PRIMARY KEY,
  project_id   UUID NOT NULL REFERENCES projects(id),
  work_item_id UUID REFERENCES work_items(id),
  worklog_id   UUID REFERENCES worklogs(id),
  summary      TEXT NOT NULL,
  severity     TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
  resolution   TEXT,
  resolved_at  TIMESTAMPTZ,
  actor_id     UUID NOT NULL REFERENCES actors(id),
  created_at   TIMESTAMPTZ NOT NULL,
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX deviations_project ON deviations (project_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX deviations_open ON deviations (project_id) WHERE resolved_at IS NULL AND deleted_at IS NULL;

-- ── conversation ─────────────────────────────────────────────────────────────

-- Scope controls context assembly and UI placement, never visibility: every
-- thread is readable by every project member (§3.6).
CREATE TABLE threads (
  id         UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id),
  scope_kind TEXT NOT NULL CHECK (scope_kind IN ('project', 'work_item', 'diagram')),
  scope_id   UUID,
  created_at TIMESTAMPTZ NOT NULL,
  -- NULLS NOT DISTINCT so the one project-scoped thread, whose scope_id is
  -- NULL, is actually unique rather than unconstrained.
  UNIQUE NULLS NOT DISTINCT (project_id, scope_kind, scope_id)
);

-- Chat is transcript, never memory (D8). Never deleted; enforced below.
CREATE TABLE messages (
  id         UUID PRIMARY KEY,
  thread_id  UUID NOT NULL REFERENCES threads(id),
  actor_id   UUID NOT NULL REFERENCES actors(id),
  role       TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'tool', 'system')),
  content    TEXT NOT NULL,
  tool_calls JSONB,
  turn_id    UUID,
  seq        BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (thread_id, seq)
);
CREATE INDEX messages_turn ON messages (turn_id) WHERE turn_id IS NOT NULL;

CREATE TABLE agent_turns (
  id           UUID PRIMARY KEY,
  project_id   UUID NOT NULL REFERENCES projects(id),
  thread_id    UUID NOT NULL REFERENCES threads(id),
  requested_by UUID NOT NULL REFERENCES users(id),
  status       TEXT NOT NULL CHECK (status IN (
                 'queued', 'running', 'complete', 'failed', 'abandoned')),
  model        TEXT,
  tokens_in    INT,
  tokens_out   INT,
  turns        INT,
  error_class  TEXT,
  heartbeat_at TIMESTAMPTZ,
  started_at   TIMESTAMPTZ,
  ended_at     TIMESTAMPTZ
);
-- One running turn per project (§5.3). A second prompt queues, visibly.
CREATE UNIQUE INDEX agent_turns_one_running ON agent_turns (project_id) WHERE status = 'running';
CREATE INDEX agent_turns_project ON agent_turns (project_id, started_at DESC);

-- ── governance ───────────────────────────────────────────────────────────────

CREATE TABLE proposals (
  id                UUID PRIMARY KEY,
  project_id        UUID NOT NULL REFERENCES projects(id),
  actor_id          UUID NOT NULL REFERENCES actors(id),
  turn_id           UUID REFERENCES agent_turns(id),
  title             TEXT NOT NULL,
  rationale         TEXT NOT NULL,
  target_kind       TEXT NOT NULL CHECK (target_kind IN ('diagram', 'plan', 'mixed')),
  status            TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'superseded')),
  decided_by        UUID REFERENCES users(id),
  decided_at        TIMESTAMPTZ,
  decision_rationale TEXT,
  applied_revision  INT,
  created_at        TIMESTAMPTZ NOT NULL,
  -- A rejection without a rationale is validation_failed at the API (§5.2).
  -- Without it the agent re-proposes what was refused and the user concludes
  -- the tool does not listen, so the invariant is held here too.
  CONSTRAINT proposal_rejection_has_rationale
    CHECK (status <> 'rejected' OR coalesce(btrim(decision_rationale), '') <> '')
);
CREATE INDEX proposals_project_status ON proposals (project_id, status, created_at DESC);

CREATE TABLE proposal_changes (
  id          UUID PRIMARY KEY,
  proposal_id UUID NOT NULL REFERENCES proposals(id),
  seq         INT NOT NULL,
  op          TEXT NOT NULL CHECK (op IN ('create', 'update', 'delete')),
  target_kind TEXT NOT NULL,
  target_id   UUID,
  before      JSONB,
  after       JSONB,
  UNIQUE (proposal_id, seq)
);

-- On a name collision the backend writes a Note; it never merges (§3.4).
-- Notes are structured facts retrieved by traversal and are never chunked into
-- the vector store.
CREATE TABLE notes (
  id           UUID PRIMARY KEY,
  project_id   UUID NOT NULL REFERENCES projects(id),
  subject_kind TEXT NOT NULL,
  subject_id   UUID,
  kind         TEXT NOT NULL CHECK (kind IN ('overlap', 'conflict', 'missing', 'clarification')),
  body         TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('open', 'resolved', 'dismissed')),
  provenance   TEXT NOT NULL CHECK (provenance IN (
                 'vlm_extracted', 'human_created', 'human_edited',
                 'agent_proposed', 'agent_committed', 'system')),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  created_at   TIMESTAMPTZ NOT NULL,
  resolved_at  TIMESTAMPTZ,
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX notes_project_status ON notes (project_id, status) WHERE deleted_at IS NULL;
CREATE INDEX notes_subject ON notes (subject_kind, subject_id) WHERE deleted_at IS NULL;

-- ── context and audit ────────────────────────────────────────────────────────

-- harness_fields are recomputed from the database and cannot drift.
-- model_fields are a hypothesis, not a record; the UI must not present them as
-- fact (§6.3). Nothing in the harness may write model_fields, and no model may
-- write harness_fields.
CREATE TABLE project_digest (
  project_id         UUID PRIMARY KEY REFERENCES projects(id),
  revision           INT NOT NULL,
  harness_fields     JSONB NOT NULL,
  model_fields       JSONB NOT NULL,
  model_fields_stale BOOLEAN NOT NULL DEFAULT FALSE,
  updated_at         TIMESTAMPTZ NOT NULL
);

-- Only spill is chunked: worklogs, messages, imported documents. Structured
-- objects are retrieved by query — chunking a note destroys the structure that
-- made it findable (§6.3).
--
-- The dimension here is asserted against the live embedding model at boot. A
-- mismatch is an error, never a silent mixed-space search.
CREATE TABLE chunks (
  id          UUID PRIMARY KEY,
  project_id  UUID NOT NULL REFERENCES projects(id),
  source_kind TEXT NOT NULL CHECK (source_kind IN ('worklog', 'message', 'document', 'note')),
  source_id   UUID NOT NULL,
  chunk_idx   INT NOT NULL,
  content     TEXT NOT NULL,
  embedding   VECTOR(1024),
  model       TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL,
  UNIQUE (source_kind, source_id, chunk_idx)
);
CREATE INDEX chunks_project ON chunks (project_id, source_kind);
CREATE INDEX chunks_embedding ON chunks USING hnsw (embedding vector_cosine_ops);

CREATE TABLE audit_log (
  id           UUID PRIMARY KEY,
  project_id   UUID REFERENCES projects(id),
  actor_id     UUID NOT NULL REFERENCES actors(id),
  on_behalf_of UUID REFERENCES users(id),
  action       TEXT NOT NULL,
  subject_kind TEXT NOT NULL,
  subject_id   UUID,
  before       JSONB,
  after        JSONB,
  -- NOT NULL so it cannot be quietly skipped. It is what distinguishes an
  -- agent applying a 14-change proposal in one operation from someone making
  -- 14 edits over an afternoon (§6.5 constraint 3).
  request_id   TEXT NOT NULL CHECK (btrim(request_id) <> ''),
  at           TIMESTAMPTZ NOT NULL
);

COMMENT ON TABLE audit_log IS
  'Append-only. Retention is: never. This log is not pruned, archived, or '
  'rotated, and no job may be added to keep it small — such a job is a '
  'regression, not housekeeping (CONTRACT.md §6.5 constraint 5). Durations are '
  'derived from it by window function and are never stored anywhere '
  '(constraint 4). The v0.1 CSV export is a SELECT over this table, which is '
  'only true if the record is complete from the first commit.';

-- Export indexes. Present from the first migration (D13): adding them a year
-- later means building an index on a table you are trying to read, at the
-- moment you most want the data.
CREATE INDEX audit_project_at ON audit_log (project_id, at);
CREATE INDEX audit_subject_at ON audit_log (subject_kind, subject_id, at);
CREATE INDEX audit_actor_at   ON audit_log (actor_id, at);
CREATE INDEX audit_action_at  ON audit_log (project_id, action, at);
CREATE INDEX audit_request    ON audit_log (request_id);

-- ── append-only enforcement ──────────────────────────────────────────────────

CREATE FUNCTION zp_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION
    '% on %.% is not permitted: this table is append-only and its retention is never (CONTRACT.md 6.5). Correct by adding a row, not by changing one.',
    TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();

-- Worklogs and messages are never deleted at all (§6.5 constraint 1). UPDATE is
-- left open: a message is persisted incrementally while a turn streams, and
-- that is a write in progress rather than a rewrite of history.
CREATE TRIGGER worklogs_no_delete BEFORE DELETE ON worklogs
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
CREATE TRIGGER worklogs_no_truncate BEFORE TRUNCATE ON worklogs
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
CREATE TRIGGER messages_no_delete BEFORE DELETE ON messages
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
CREATE TRIGGER messages_no_truncate BEFORE TRUNCATE ON messages
  FOR EACH STATEMENT EXECUTE FUNCTION zp_append_only();
